const rows = $input.all();
const categories = rows
  .map(r => r.json)
  .filter(j => j && !j.error && j.id)
  .map(j => ({
    id: Number(j.id),
    name: j.name || '',
    type: j.type || 'MAIN',
    parentName: j.parentName || null
  }));
return [{ json: { categories, count: categories.length } }];
